{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the total number of complete products (limited by the smallest component count), maximize total component output, or minimize total production hours used?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "Are the production rates in the table (e.g., Workshop A produces 10 units/hour of Component 1) the same for every workshop-component pair as listed?",
    "Is the time a workshop spends on a component simply (units produced) divided by that rate?"
  ],
  "rationale": "The response contains two distinct clarification requests: one confirming the validity of the production rates for all pairs, and another confirming the calculation method for time spent. These can be answered independently."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a workshop split its available hours across all three components (i.e., produce any mix of components), or is each workshop restricted to producing only one specific component?"
  ],
  "rationale": "The response asks a single clarification question regarding workshop production flexibility, presenting two mutually exclusive options for the user to choose from."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do the component units have to be whole numbers (integer), or can they be fractional (continuous) values?"
  ],
  "rationale": "The response asks a single clarification question regarding the data type (integer vs. continuous) of the component units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If a workshop has leftover hours that it does not allocate to any component, is that simply allowed (unused capacity is free), or is there any penalty or requirement to use all available hours?"
  ],
  "rationale": "The response asks for a single policy decision regarding the treatment of unused workshop capacity, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any demand limit or upper bound on how many of each component (or how many complete products) can be produced, or is the only limit the workshops' production capacities?"
  ],
  "rationale": "The response asks a single clarification question regarding whether production is limited by demand caps or solely by workshop capacities."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Regarding the number of complete products to maximize — should it be an integer (you can only assemble whole products), or is it acceptable to report a fractional value (e.g., 12.5 products)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the granularity of the objective variable (integer vs. fractional), which constitutes one semantically independent question."
}

{
